# Output.ps1
# Builds the files that are not tied to one resource (providers, variables, locals, outputs, tfvars,
# backend config) and writes every generated file the same way each time.

function Get-GeneratedHeader {
    param([Parameter(Mandatory)]$Context)
    return @(
        '# Generated by New-TerraformConfiguration.ps1. Do not edit by hand.'
        "# Source: $($Context.SpecFileName) (sha256 $($Context.SpecSha256))"
        '# Change the spec and generate again; the same spec always produces the same files.'
    ) -join "`n"
}

function New-ProvidersFile {
    $terraform = New-HclTopLevelBlock 'terraform' @(
        (New-HclAttr 'required_version' '">= 1.6.0"')
        (New-HclBlock 'required_providers' @(
                (New-HclMap 'azurerm' ([ordered]@{ source = '"hashicorp/azurerm"'; version = '"~> 4.0"' }))
            ))
        # Partial backend: the storage location is supplied per environment with -backend-config (IG-021).
        (New-HclBlock 'backend "azurerm"' @())
    )
    $provider = New-HclTopLevelBlock 'provider "azurerm"' @(
        (New-HclBlock 'features' @())
        # Lets Terraform reach storage data planes with Entra ID so shared key access can stay disabled (section 6.3).
        (New-HclAttr 'storage_use_azuread' 'true')
    )
    return @($terraform, $provider) -join "`n`n"
}

function New-VariablesFile {
    param([Parameter(Mandatory)]$Context)
    $envList = '[' + (($Context.Environments | ForEach-Object { ConvertTo-HclString $_ }) -join ', ') + ']'
    $blocks = [System.Collections.Generic.List[string]]::new()
    $blocks.Add((New-HclTopLevelBlock 'variable "environment"' @(
                (New-HclAttr 'description' '"Environment name. Selects the values in environments/<name>.tfvars."')
                (New-HclAttr 'type' 'string')
                (New-HclBlock 'validation' @(
                        (New-HclAttr 'condition' "contains($envList, var.environment)")
                        (New-HclAttr 'error_message' ('"environment must be one of: ' + ($Context.Environments -join ', ') + '."'))
                    ))
            )))
    foreach ($variable in $Context.Variables.Values) {
        $blocks.Add((New-HclTopLevelBlock ('variable "{0}"' -f $variable.Name) @(
                    (New-HclAttr 'description' (ConvertTo-HclString $variable.Description))
                    (New-HclAttr 'type' $variable.Type)
                )))
    }
    return $blocks -join "`n`n"
}

function New-LocalsFile {
    param([Parameter(Mandatory)]$Context)
    $spec = $Context.Spec

    $tags = [ordered]@{}
    foreach ($key in $spec['tags'].Keys) { $tags[$key] = ConvertTo-HclValue $spec['tags'][$key] }
    $tags['environment'] = 'var.environment'

    $names = [ordered]@{}
    foreach ($resource in $Context.Resources) {
        if ($resource.Type -eq 'storage_account' -or $script:ResourceTypes[$resource.Type].Abbreviation -or $resource.Key) {
            $names[(Get-NameId $resource)] = Get-NameHcl $resource
        }
        if ($resource.Type -eq 'function_app') { $names[(Get-NameId $resource) + '_plan'] = Get-NameHcl $resource 'plan' }
    }

    return New-HclTopLevelBlock 'locals' @(
        (New-HclAttr 'org' (ConvertTo-HclValue $spec['organization']))
        (New-HclAttr 'workload' (ConvertTo-HclValue $spec['workload']))
        (New-HclAttr 'region' (ConvertTo-HclValue $spec['region']))
        (New-HclAttr 'region_abbr' (ConvertTo-HclValue $spec['region_abbreviation']))
        (New-HclMap 'tags' $tags)
        (New-HclMap 'names' $names)
    )
}

function New-OutputsFile {
    param([Parameter(Mandatory)]$Context)
    $blocks = foreach ($output in $Context.Outputs.Values) {
        $body = @(
            (New-HclAttr 'description' (ConvertTo-HclString $output.Description))
            (New-HclAttr 'value' $output.Value)
        )
        if ($output.Sensitive) { $body += (New-HclAttr 'sensitive' 'true') }
        New-HclTopLevelBlock ('output "{0}"' -f $output.Name) $body
    }
    return @($blocks) -join "`n`n"
}

function New-TfVarsFile {
    param([Parameter(Mandatory)]$Context, [Parameter(Mandatory)][string]$Environment)
    $values = [ordered]@{ environment = ConvertTo-HclString $Environment }
    foreach ($variable in $Context.Variables.Values) { $values[$variable.Name] = ConvertTo-HclValue $variable.Values[$Environment] }
    return Format-HclBody -Items @($values.Keys | ForEach-Object { New-HclAttr $_ $values[$_] }) -Indent 0 | Join-String -Separator "`n"
}

function New-BackendFile {
    param([Parameter(Mandatory)]$Context, [Parameter(Mandatory)][string]$Environment)
    $state = $Context.Spec['state']
    $items = @(
        (New-HclAttr 'resource_group_name' (ConvertTo-HclValue $state['resource_group_name']))
        (New-HclAttr 'storage_account_name' (ConvertTo-HclValue $state['storage_account_name']))
        (New-HclAttr 'container_name' (ConvertTo-HclValue $state['container_name']))
        (New-HclAttr 'key' (ConvertTo-HclString ('{0}-{1}.tfstate' -f $Context.Spec['service'], $Environment)))
        (New-HclAttr 'use_azuread_auth' 'true')
    )
    return Format-HclBody -Items $items -Indent 0 | Join-String -Separator "`n"
}

function Write-GeneratedFile {
    <# UTF-8 without BOM, LF line endings, exactly one trailing newline. #>
    param([Parameter(Mandatory)][string]$Path, [Parameter(Mandatory)][string]$Content)
    $directory = Split-Path -Parent $Path
    if (-not (Test-Path -LiteralPath $directory)) { New-Item -ItemType Directory -Path $directory -Force | Out-Null }
    $text = $Content.Replace("`r`n", "`n").TrimEnd("`n") + "`n"
    [System.IO.File]::WriteAllText($Path, $text, [System.Text.UTF8Encoding]::new($false))
}
